class UspsAddress(BaseModel):
    model_config = ConfigDict(
        extra="allow",
    )
    id: ID
    dataset: Annotated[str, Field(description="Identifies the address as sourced from USPS", title="USA Dataset")]
    country: Annotated[str, Field(description="  Full country names (ISO 3166)\n", title="Country")]
