def _dataset_tag(tags: dict[str, str]) -> Callable[[object], str]:
    """Select a native record model by dataset; unknown datasets stay dictionaries."""

    def tag(value: object) -> str:
        if isinstance(value, dict):
            dataset = cast("dict[str, object]", value).get("dataset")
        else:
            dataset = getattr(value, "dataset", None)
        return tags.get(dataset, "unknown") if isinstance(dataset, str) else "unknown"

    return tag


