    line_2: Annotated[str, Field(description="Address Line 2", max_length=200, min_length=0)]
    line_3: Annotated[str, Field(description="Address Line 3", max_length=200, min_length=0)]
    line_4: Annotated[str, Field(description="Address Line 4", max_length=200, min_length=0)]
    line_5: Annotated[str, Field(description="Address Line 5", max_length=200, min_length=0)]
    line_6: Annotated[str, Field(description="Address Line 6", max_length=200, min_length=0)]
    line_7: Annotated[str, Field(description="Address Line 7", max_length=200, min_length=0)]
    line_8: Annotated[str, Field(description="Address Line 8", max_length=200, min_length=0)]
    line_9: Annotated[str, Field(description="Address Line 9", max_length=200, min_length=0)]
    department: Annotated[
        str,
        Field(
            description="The department or division within an organisation, e.g. `Accounts Department`. If the department element exists, then the organisation must also exist.",
            max_length=60,
            min_length=0,
        ),
    ]
    organisation: Annotated[
        str, Field(description="Organisation name, e.g. `Oak Tree Limited`.", max_length=60, min_length=0)
    ]
    sub_building_name: Annotated[
        str,
        Field(
            description="The sub-building refers to an apartment, flat or unit within a building, e.g. `Flat 1`.",
            max_length=60,
            min_length=0,
        ),
    ]
    building_name: Annotated[
        str,
        Field(
            description="The name given to the building, e.g. `Rose Cottage`. Prepended by sub building, if any, when the sub building does not appear on a line to itself. The building name is omitted if it is the same as either the Organisation or Building Group.",
            max_length=60,
            min_length=0,
        ),
    ]
    building_number: Annotated[
        str,
        Field(
            description="A number associated with the whole building. The building number may have a numeric and an alphanumeric component, which are concatenated e.g. 2A, or alternatively will have a simple building number or a complex building number. The building number always relates to the whole building and not a sub-unit within it.\nA complex building number may be one of the following:\n  - Dual. Two numbers separated by '/' e.g. 63/64 = 63, 64\n  - Sequence. An odd or even sequence of numbers with lower and upper bound separated by an underscore '_' e.g. `1_5` = 1,3,5 and `2_6` = 2,4,6\n  - Range. A range of consecutive numbers with lower and upper bound separated by a dash '-' e.g. `63-66` = 63, 64, 65, 66\nThe building number never appears on a line by itself and can prepend Building Group, Primary Thoroughfare or Primary Locality.",
            max_length=40,
            min_length=0,
        ),
    ]
    building_group: Annotated[
        str,
        Field(
            description="A building group is a collection of buildings with a collective name, located on or near the same thoroughfare, e.g. `Marrian Terrace`.",
            max_length=60,
            min_length=0,
        ),
    ]
    primary_thoroughfare: Annotated[
        str,
        Field(
            description="The name of the thoroughfare on which premises are located, e.g. `Griffith Road`. It may appear on a line by itself or be appended to either a sub building or building number.\n\nAddresses with thoroughfares can sometimes have the thoroughfare excluded where a Building Group exists, such as a Retail Centre or Business Park, and the thoroughfare is not part of the Postal Address.",
            max_length=40,
            min_length=0,
        ),
    ]
    secondary_thoroughfare: Annotated[
        str,
        Field(
            description="It is never present without a primary thoroughfare. The primary thoroughfare is dependent on the secondary thoroughfare and appears before the secondary thoroughfare in any address.\n\nSecondary thoroughfare are generally used to assist locating a primary thoroughfare.",
            max_length=40,
            min_length=0,
        ),
    ]
    primary_locality: Annotated[
        str,
        Field(
            description="First locality elements which can refer to areas, districts, industrial estates, towns, etc.\n\nThe primary locality refers to the specific place the address is.\n\nIn urban areas, the primary locality can be required to distinguish between two thoroughfares of the same name in the same district or town. Industrial estates with named thoroughfares are also held as localities. In rural areas the primary locality is generally a townland name.",
            max_length=40,
            min_length=0,
        ),
    ]
    secondary_locality: Annotated[
        str,
        Field(
            description="Never present without a primary locality. The secondary locality has a wider geographic scope than the primary locality.\n\nIt is the secondary locality therefore which differentiates addresses with the same primary locality name within the same county.\n\nSecondary localities are more likely to be required for rural addresses.\n\nSecond locality elements which can refer to areas, districts, industrial estates, towns, etc\n\nThe secondary locality helps identify where the primary locality is located.",
            max_length=40,
            min_length=0,
        ),
    ]
    tertiary_locality: Annotated[
        str,
        Field(
            description='Also known as the Post Town.\n\nThe name of the post town associated with the premises for postal delivery purposes. This includes Dublin Postal Districts "Dublin 1" to "Dublin 24".\n\nThe post town is a significant element of the Postal Address, however it is not always populated in an address. The official post office guide, Eolaí an Phoist, describes post towns in the following manner:\n\n"A provincial postal address may include the name of a town or village several miles distant, with which the addressee has little or no connection, and, in some places, especially if this residence happens to be near a county boundary, the name of the neighbouring county instead of the county in which he actually resides. The explanation is that the main mail despatches have to be sent for more detailed sub division to certain centres known as POST TOWNS, chosen because of their accessibility and convenience."',
            max_length=40,
            min_length=0,
        ),
    ]
    post_county: Annotated[
        str,
        Field(
            description="One of the 26 Counties in the Republic of Ireland. These counties are sub-national divisions used for the purposes of administrative, geographical and political demarcation. Post County is the County associated with the Post Town, not the geographic county in which the building is located. The Post County is normally used as part of the Postal Address with some exceptions e.g. Dublin Postal Districts where the Post County is not used and some Post Towns (e.g. Tipperary, Kildare, etc.) that have the same name as the Post County.",
            max_length=30,
            min_length=0,
        ),
    ]
    eircode: Annotated[
        str,
        Field(
            description="The seven character Eircode has an A65 F4E2 format. The Eircode is a mandatory address element. The last line of a Postal Address will contain the Eircode, displayed with a space. e.g. `A65 F4E2`.\n\nThe Eircode is always the last line of a Postal Address generated within the state, e.g. if an address has four lines then the Eircode will be on its own on Address Line 5. For inbound international mail the country name IRELAND should be appended as the last line of the Postal Address.",
            max_length=60,
            min_length=0,
        ),
    ]
    address_reference: Annotated[
        str,
        Field(
            description="The address reference is the An Post GeoDirectory address reference identifier used by the Universal Service Provider.",
            max_length=16,
            min_length=0,
        ),
    ]
    longitude: Longitude
    latitude: Latitude


