class UsaVerifyMatch(BaseModel):
    model_config = ConfigDict(
        extra="allow",
    )
    query: Annotated[str, Field(description="Submitted query")]
    query_city: Annotated[str, Field(description="Submitted city")]
    query_state: Annotated[str, Field(description="Submitted state")]
    query_zip_code: Annotated[str, Field(description="Submitted zip_code")]
    match: Annotated[
        UsaCassVerifiedAddress | Address,
        Field(
            description="Nearest matching address. A CASS verified address in the United States. Elsewhere, the address in the same format Retrieve Address returns, with the raw dataset record in `native`\n"
        ),
    ]
    count: Annotated[
        float,
        Field(
            description="The number of addresses we matched to the input. We return the closest match by default.\n",
            ge=0.0,
            le=10.0,
        ),
    ]
    fit: Annotated[
        float,
        Field(
            description="A score represented as number between 1 and 0. Fit compares the address elements present in your query against the matching address elements. It does not incorporate elements you have not presented in the score. A partial address (e.g. 123 Main St) will have a fit of 1 even though it is missing city and zip code. Its confidence score will be less than 1 however because it is missing some crucial elements.\n",
            ge=0.0,
            le=1.0,
        ),
    ]
    confidence: Annotated[
        float,
        Field(
            description="A confidence score represented as number between 1 and 0. 1 indicates a full match. 0 indicates no complete matching elements.\n",
            ge=0.0,
            le=1.0,
        ),
    ]
    match_information: Annotated[
        str,
        Field(
            description="Additional information about the match.\n\nThis information is for human consumption and may not be present in all responses.\n",
            examples=[
                "Single Response - The delivery address was found in the National Database and no further information was required."
            ],
        ),
    ]
    address_line_one: Annotated[str, Field(description="Primary delivery address\n", examples=["123 Main St"])]
    address_line_two: Annotated[str, Field(description="Secondary address information\n", examples=[""])]
    city: Annotated[str, Field(description="City name\n", examples=["Springfield"])]
    state: Annotated[str, Field(description="State name\n", examples=["CO"])]
    zip_code: Annotated[str, Field(description="ZIP code\n", examples=["81073-1119"])]
    country_iso_2: Annotated[str, Field(description="2-letter ISO country code\n", examples=["US"])]


type AddressVerifyResult = UsaVerifyMatch | UsaVerifyNoMatch
